/* eslint-disable no-undef */
/**
 * Campus Mart service worker (PRD §54–55).
 *
 * Hand-written and small, rather than generated by a plugin, because it does
 * only three jobs and each one has a rule behind it:
 *
 *  1. **Receive pushes and open the right page.** The payload is rendered by the
 *     server; this file never composes wording of its own.
 *  2. **Answer navigations when the network is gone** with an offline page, so a
 *     student in a lecture-hall basement sees Campus Mart rather than a browser
 *     error.
 *  3. **Never cache anything that belongs to somebody.** Only build assets and
 *     the offline shell are cached. API responses, orders, hand-over codes and
 *     prices are always fetched live — a stale delivery status is worse than no
 *     delivery status, and a cached OTP on a shared phone is a security problem.
 *
 * Written in plain JS and served from `public/` because a service worker must be
 * a real file at a stable URL with page-level scope. It is not bundled, so it
 * uses no imports and no syntax that needs compiling.
 */

const CACHE = "campus-mart-v1";
const OFFLINE_URL = "/offline";

// Pre-cached at install so the offline page is available the first time the
// network disappears, not the second.
const PRECACHE = [OFFLINE_URL, "/icon.svg"];

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // `reload` bypasses the HTTP cache: an offline page that was itself served
      // from a stale cache would defeat the point.
      await cache.addAll(PRECACHE.map((url) => new Request(url, { cache: "reload" })));
      // Take over without waiting for every tab to close. Safe here because the
      // worker holds no versioned application logic.
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // Drop caches from earlier versions of this worker so a deploy cannot leave
      // last week's shell on a phone.
      const names = await caches.keys();
      await Promise.all(names.filter((name) => name !== CACHE).map((name) => caches.delete(name)));
      await self.clients.claim();
    })(),
  );
});

/**
 * Navigations only, and network-first.
 *
 * Anything that is not a page navigation is left to the browser: Next.js already
 * serves hashed build assets with correct cache headers, and API requests must
 * never be answered from a cache. If the network fails on a navigation, the
 * offline page is returned instead of a browser error.
 */
self.addEventListener("fetch", (event) => {
  const { request } = event;

  if (request.method !== "GET" || request.mode !== "navigate") return;

  event.respondWith(
    (async () => {
      try {
        return await fetch(request);
      } catch {
        const cache = await caches.open(CACHE);
        const offline = await cache.match(OFFLINE_URL);
        return (
          offline ??
          new Response("You are offline.", {
            status: 503,
            headers: { "Content-Type": "text/plain; charset=utf-8" },
          })
        );
      }
    })(),
  );
});

/**
 * A push arrived.
 *
 * The payload is JSON the server already rendered — title, body, href and the
 * notification id. This worker does not know what a delivery is, and that is
 * deliberate: the wording lives in one catalogue on the server, so a phone that
 * has not been reopened in a month still shows current copy.
 *
 * `tag` collapses updates about the same subject, so five status changes on one
 * order replace each other on the lock screen instead of stacking.
 */
self.addEventListener("push", (event) => {
  if (!event.data) return;

  let payload = {};
  try {
    payload = event.data.json();
  } catch {
    // A push we cannot parse is not shown. Browsers may penalise a worker that
    // receives a push and displays nothing, but showing "undefined" to a student
    // is worse than that.
    return;
  }

  const title = payload.title || "Campus Mart";
  const options = {
    body: payload.body || "",
    icon: "/icon.svg",
    badge: "/icon.svg",
    tag: payload.tag || undefined,
    // Replace quietly: a re-notify for a superseded status would buzz twice.
    renotify: false,
    data: {
      href: payload.href || "/",
      notificationId: payload.notificationId || null,
    },
  };

  event.waitUntil(self.registration.showNotification(title, options));
});

/**
 * The notification was tapped.
 *
 * An already-open Campus Mart tab is focused and navigated rather than opening a
 * second one, which is what a student expects from an installed app.
 */
self.addEventListener("notificationclick", (event) => {
  event.notification.close();

  const href = (event.notification.data && event.notification.data.href) || "/";

  event.waitUntil(
    (async () => {
      const url = new URL(href, self.location.origin);

      const clientList = await self.clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      });

      for (const client of clientList) {
        // Same origin only — `matchAll` can include windows this worker does not
        // control, and navigating a foreign page would be wrong.
        if (new URL(client.url).origin === url.origin && "focus" in client) {
          await client.focus();
          if ("navigate" in client) await client.navigate(url.href);
          return;
        }
      }

      await self.clients.openWindow(url.href);
    })(),
  );
});

/**
 * The push service replaced this subscription.
 *
 * Browsers rotate subscriptions without asking. Without this handler the phone
 * silently stops receiving notifications and nobody finds out. Re-subscribing
 * with the same application key and telling the server keeps the row current.
 *
 * The old endpoint is not deleted from here: the server drops endpoints when a
 * send returns 404/410, which is the one signal that is actually reliable.
 */
self.addEventListener("pushsubscriptionchange", (event) => {
  event.waitUntil(
    (async () => {
      const applicationServerKey =
        (event.oldSubscription && event.oldSubscription.options
          ? event.oldSubscription.options.applicationServerKey
          : null) || null;

      if (!applicationServerKey) return;

      try {
        const subscription = await self.registration.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey,
        });

        await fetch("/api/notifications/subscribe", {
          method: "POST",
          credentials: "same-origin",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(subscription.toJSON()),
        });
      } catch {
        // Nothing useful to do: the user is not looking, and the opt-in control
        // re-registers on their next visit.
      }
    })(),
  );
});
